  `notes` text COLLATE utf8mb4_general_ci,
  `letter_content` text COLLATE utf8mb4_general_ci,
  `created_by` int DEFAULT NULL,
  `approved_by` int DEFAULT NULL,
  `admin_approved_by` int DEFAULT NULL,
  `admin_approved_date` datetime DEFAULT NULL,
  `admin_approval_action` enum('send_to_user','send_to_ktt') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `admin_approval_notes` text COLLATE utf8mb4_general_ci,
  `rejected_by_ktt_user_id` int DEFAULT NULL,
