  `ktt1_approved_date` datetime DEFAULT NULL,
  `ktt2_approved_by` int DEFAULT NULL,
  `ktt2_approved_date` datetime DEFAULT NULL,
  `ktt_msm_status` enum('pending','approved','rejected') COLLATE utf8mb4_general_ci DEFAULT 'pending' COMMENT 'KTT MSM approval status',
  `ktt_ttn_status` enum('pending','approved','rejected') COLLATE utf8mb4_general_ci DEFAULT 'pending' COMMENT 'KTT TTN approval status',
  `requires_ktt_msm_review` tinyint(1) DEFAULT '1' COMMENT 'Flag: should KTT MSM review this appointment?',
  `requires_ktt_ttn_review` tinyint(1) DEFAULT '1' COMMENT 'Flag: should KTT TTN review this appointment?',
  `resubmit_reason` text COLLATE utf8mb4_general_ci COMMENT 'Combined admin + KTT rejection notes for user',
  `last_rejected_by_ktt` enum('msm','ttn') COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Which KTT type rejected last (msm or ttn)',
  `approved_date` datetime DEFAULT NULL,
  `approval_notes` text COLLATE utf8mb4_general_ci,
  `final_approval_date` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `resubmit_count` int DEFAULT '0',
  `last_rejection_notes` text COLLATE utf8mb4_general_ci COMMENT 'Stores rejection reason from last KTT rejection',
  `last_rejection_by_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT 'Stores name of KTT who rejected',
  `last_rejection_date` datetime DEFAULT NULL COMMENT 'Stores date of last rejection',
  `parent_appointment_id` int DEFAULT NULL,
  `is_resubmission` tinyint(1) DEFAULT '0',
  `resubmit_type` enum('certificate','data_update') COLLATE utf8mb4_general_ci DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `deleted_by` int DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

